insert into public.reports (
  id, title, category, description, location_name, latitude, longitude, status, created_at, user_id
) values
  ('00000000-0000-4000-8000-000000000101', 'Bike taken from rack', 'Theft', 'A locked commuter bike was taken from the rack outside the south entrance. Reported to campus security; please use the racks inside the west doors for now.', 'Thompson Library, south entrance', 40.00072, -83.01456, 'active', now() - interval '21 minutes', null),
  ('00000000-0000-4000-8000-000000000102', 'Phone snatched near bus stop', 'Theft', 'A phone was taken near the southbound stop around dusk. No injuries reported. Stay aware while waiting near the curb.', 'High Street & 15th Avenue', 39.99782, -83.00883, 'active', now() - interval '1 hour 48 minutes', null),
  ('00000000-0000-4000-8000-000000000103', 'Suspicious activity reported', 'Safety', 'Several people reported someone checking door handles near the east patio. Building staff have been notified and are monitoring the area.', 'Ohio Union, east patio', 39.99748, -83.00763, 'active', now() - interval '3 hours 12 minutes', null),
  ('00000000-0000-4000-8000-000000000104', 'Attempted bike theft', 'Theft', 'A lock was cut but the bike was left behind. The owner has filed a report. Consider using a U-lock and registering bikes with the university.', 'Dreese Laboratories, west side', 40.00232, -83.01717, 'active', now() - interval '5 hours 30 minutes', null),
  ('00000000-0000-4000-8000-000000000105', 'Robbery reported near campus edge', 'Robbery', 'A robbery was reported near the intersection. The person involved is safe and has contacted police. Take a well-lit route and travel with someone if possible.', 'North High Street & West 11th Avenue', 40.00421, -83.01022, 'active', now() - interval '8 hours', null),
  ('00000000-0000-4000-8000-000000000106', 'Wallet found and turned in', 'Other', 'A wallet was found in the first-floor reading area and handed to the library service desk.', 'Thompson Library, east desk', 40.00095, -83.0134, 'resolved', now() - interval '29 hours', null),
  ('00000000-0000-4000-8000-000000000107', 'Unlit path by the Oval', 'Safety', 'A stretch of path lighting was out. Facilities have replaced the bulbs and the path is lit again.', 'Oval, southeast path', 39.99825, -83.01312, 'resolved', now() - interval '54 hours', null)
on conflict (id) do nothing;
